CREATE TABLE access_requests (id VARCHAR(64) PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, display_name VARCHAR(120) NOT NULL, requested_role VARCHAR(16) NOT NULL, status VARCHAR(32) NOT NULL, email_verified_at VARCHAR(40) NULL, reviewed_by_user_id VARCHAR(64) NULL, reviewed_at VARCHAR(40) NULL, review_reason TEXT NULL, created_user_id VARCHAR(64) NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, CONSTRAINT chk_access_requests_role CHECK (requested_role IN ('family','volunteer','commander')), CONSTRAINT chk_access_requests_status CHECK (status IN ('pending_verification','pending_review','approved','rejected')), CONSTRAINT fk_access_requests_reviewer FOREIGN KEY (reviewed_by_user_id) REFERENCES users(id), CONSTRAINT fk_access_requests_user FOREIGN KEY (created_user_id) REFERENCES users(id));
-- statement-break
CREATE INDEX idx_access_requests_status_created ON access_requests(status, created_at);
-- statement-break
CREATE TABLE auth_email_tokens (id VARCHAR(64) PRIMARY KEY, access_request_id VARCHAR(64) NULL, user_id VARCHAR(64) NULL, purpose VARCHAR(32) NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, expires_at VARCHAR(40) NOT NULL, consumed_at VARCHAR(40) NULL, created_at VARCHAR(40) NOT NULL, CONSTRAINT chk_auth_email_tokens_purpose CHECK (purpose IN ('access_request_verify','password_setup')), CONSTRAINT chk_auth_email_tokens_subject CHECK ((access_request_id IS NOT NULL) <> (user_id IS NOT NULL)), CONSTRAINT fk_auth_email_tokens_request FOREIGN KEY (access_request_id) REFERENCES access_requests(id) ON DELETE CASCADE, CONSTRAINT fk_auth_email_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
-- statement-break
CREATE TABLE message_deliveries (id VARCHAR(64) PRIMARY KEY, channel VARCHAR(32) NOT NULL, template VARCHAR(64) NOT NULL, subject_type VARCHAR(64) NOT NULL, subject_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, attempt_count INT NOT NULL, failure_reason VARCHAR(200) NULL, created_at VARCHAR(40) NOT NULL, delivered_at VARCHAR(40) NULL, CONSTRAINT chk_message_deliveries_status CHECK (status IN ('delivered','failed','not_configured')), CONSTRAINT chk_message_deliveries_attempts CHECK (attempt_count >= 0));
